        # $imports: arrayref of imported symbols (empty for full import)

        my $graph = $self->graph;
        my $current_control = $self->current_control;

        my $attributes = {
            type => $type,
            module => $module,
            imports => $imports
        };

        my $node_id = $self->next_node_id();
        my $use_stmt = Chalk::IR::Node->new(
