        my $node_id = $self->next_node_id();
        my $field_access = Chalk::IR::Node->new(
            id            => $node_id,
            op            => 'FieldAccess',
            inputs        => [$current_control, $object_node->id],
            attributes    => $attributes,
        );
        $graph->add_node($field_access);
        return $field_access;
    }

