# Dereference a scalar reference: $$ref
method build_scalar_deref_node($ref_var_name) {
    # Get the reference from context
    my $ref_label = "lexical:$ref_var_name";
    my $ref_id = $context->($ref_label);

    # Create ScalarDeref node
