    method build_hash_exists_node($hash_node, $key_node) {
        # Create HashExists node for checking if key exists in hash
        my $hash_ref = { op => 'NodeRef', node_id => $hash_node->id };
        my $key_ref = { op => 'NodeRef', node_id => $key_node->id };
        my $attributes = {
