# ABOUTME: Implements $$ref by performing context lookup via reference's (context, label) pair
use 5.42.0;
use experimental qw(class);
use utf8;

class Chalk::IR::Node::ScalarDeref :isa(Chalk::IR::Node::Base) {
    field $ref_id :param :reader;  # Node ID of the reference

    method op() { 'ScalarDeref' }

    method to_hash() {
        return {
            id     => $self->id,
            op     => 'ScalarDeref',
            inputs => $self->inputs,
            attributes => {
                ref_id => $ref_id,
            },
        };
    }

    method execute($context) {
        # Get the reference object
        my $ref_obj = $context->("node:$ref_id");
        warn "ScalarDeref: ref_obj = " . ($ref_obj // "undef");
        warn "ScalarDeref: ref_obj->{ref_context} = " . ($ref_obj->{ref_context} // "undef") if ref($ref_obj) eq 'HASH';

        # Extract the target context and label from the reference
        my $target_context = $ref_obj->{ref_context};
        my $target_label = $ref_obj->{ref_label};
        warn "ScalarDeref: target_label = " . ($target_label // "undef");

        # Perform lookup in the target context
        my $node_id = $target_context->($target_label);
        warn "ScalarDeref: node_id from target_context = " . ($node_id // "undef");

        # Resolve the node ID to get the actual value
        my $value = $context->("node:$node_id");
        warn "ScalarDeref: final value = " . ($value // "undef");

        return $value;
    }
}

