        $graph->add_node($var_read);
        return $var_read;
    }

    # Assign through a dereferenced reference: $$ref = value
    method build_scalar_deref_assign_node($ref_var_name, $value_node) {
        # Get the reference from context
        my $ref_label = "lexical:$ref_var_name";
        my $ref_id = $context->($ref_label);
        my $ref_node = $graph->get_node($ref_id);

        # Get the target context and label from the reference
        my $target_ctx = $ref_node->target_context;
        my $target_label = $ref_node->target_label;

        # Extend the target context with the new value
        my $new_ctx = Chalk::IR::Context->extend_context(
            $target_ctx,
            $target_label,
            $value_node->id
        );

        # Update the builder's context to reflect this change
        # This is simplified - in reality, we need to handle this more carefully
        $context = $new_ctx;

        # Return the value node for chaining
        return $value_node;
    }

}

